408	\begin{lemma}[Triangle inequality for vectors squared]\label{prop:triangle-inequality-for-vectors-squared}
409		\lean{MIPStarRE.LDT.Preliminaries.triangleInequalityForVectorsSquared}
410		\leanok
411		For vectors $\ket{\psi_1},\dots,\ket{\psi_k}$,
412		\[
413			\bigl\lVert \ket{\psi_1}+\cdots+\ket{\psi_k} \bigr\rVert^2 \le k(\lVert\ket{\psi_1}\rVert^2+\cdots+\lVert\ket{\psi_k}\rVert^2).
414		\]
415	\end{lemma}
416	\begin{proof}
417		\leanok
418		First,
419		\begin{equation}\label{eq:prop-for-real-numbers}
420			(x_1+\cdots+x_k)^2 \le k(x_1^2+\cdots+x_k^2)
421		\end{equation}
422		for all real numbers $x_1,\dots,x_k$. Apply \eqref{eq:prop-for-real-numbers} to $x_i=\lVert\ket{\psi_i}\rVert$ and combine it with the triangle inequality.
423	\end{proof}
