679	\begin{lemma}[Bounding the missing mass of a close submeasurement]\label{lem:completion-missing-mass-bound}
680		\lean{MIPStarRE.LDT.Preliminaries.completionMissingMassBound}
681		\leanok
682		\uses{def:strong-self-consistency, def:approx_delta, lem:self-consistency-same-side-square}
683		Let $A=\{A_a\}$ be a measurement that is $\zeta$-strongly self-consistent, and let $B=\{B_a\}$ be a submeasurement such that $A_a \ot I \approx_\delta B_a \ot I$. Writing $B=\sum_a B_a$, one has
684		\[
685			\lVert (I-B) \ot I\ket{\psi} \rVert^2 \le 2\sqrt\delta + \zeta.
686		\]
687	\end{lemma}
688	\begin{proof}
689		\leanok
690		Since $0 \le I-B \le I$, the left-hand side is at most $1-\bra{\psi} B \ot I \ket{\psi}$. Compare $\sum_a \bra{\psi} B_a^2 \ot I \ket{\psi}$ with $\sum_a \bra{\psi} A_a B_a \ot I \ket{\psi}$ and then with $\sum_a \bra{\psi} A_a^2 \ot I \ket{\psi}$ using the $\approx_\delta$ hypothesis, and finish with Lemma~\ref{lem:self-consistency-same-side-square}.
691	\end{proof}
