693	\begin{lemma}[Completing a close submeasurement to a full measurement]\label{prop:completing-to-measurement}
694		\lean{MIPStarRE.LDT.Preliminaries.completingToMeasurement}
695		\leanok
696		\uses{def:measurement-completion, def:strong-self-consistency, def:approx_delta, prop:triangle-inequality-for-vectors-squared, prop:easy-approx-from-approx-delta, prop:cool-prop}
697		Let $A=\{A_a\}$ be a measurement that is $\zeta$-strongly self-consistent, let $B=\{B_a\}$ be a submeasurement such that $A_a \ot I \approx_\delta B_a \ot I$, and let $C$ be the measurement obtained by adding the missing mass $I-B$ to one distinguished answer $a^*$. Then
698		\[
699			A_a \ot I \approx_{2\delta + 4\sqrt\delta + 2\zeta} C_a \ot I.
700		\]
701	\end{lemma}
702	\begin{proof}[Proof of \ref{prop:completing-to-measurement}]
703		\proves{prop:completing-to-measurement}
704		\leanok
705		\uses{prop:triangle-inequality-for-vectors-squared, prop:easy-approx-from-approx-delta, prop:cool-prop}
706		By Lemma~\ref{prop:triangle-inequality-for-vectors-squared},
707		\[
708			\sum_a \lVert(A_a-C_a)\ot I \ket{\psi} \rVert^2
709			\leq 2\delta + 2 \cdot \lVert(I-B)\ot I \ket{\psi}\rVert^2.
710		\]
711		It remains to bound the residual term. Since $0 \le I-B \le I$,
712		\begin{align}
713			\lVert(I-B) \ot I \ket{\psi}\rVert^2
714			 & \leq 1 -\sum_a \bra{\psi} B_a^2 \ot I \ket{\psi}.
715			\label{eq:to-return-later-whatevs}

