 663		\begin{lemma}[Rank reduction]\label{lem:projective-low-rank-sum}
 664			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.projectiveLowRankSum}
 665			\leanok
 666			There exists a set of projection matrices $\{Q_a\}$ such that
 667			\begin{equation*}
 668				A_a \ot I \approx_{12\sqrt{\zeta}} Q_a \ot I.
 669			\end{equation*}
 670			and
 671			\begin{equation*}
 672				Q:= \sum_a Q_a \leq (1+2\sqrt{\zeta}) \cdot I.
 673			\end{equation*}
 674			Furthermore,
 675			\begin{equation*}
 676				\sum_a \mathrm{rank}(Q_a) \leq d.
 677			\end{equation*}
 678		\end{lemma}
 679		\begin{proof}
 680			\leanok
 681			\uses{lem:projective-non-measurement, lem:small-overlap-averaging, prop:triangle-inequality-for-approx_delta}
 682			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.projectiveLowRankSum_of_projectors}
 683			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.projectiveLowRankSum_of_rank_bound}
 684			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.projectiveLowRankSum_of_spectralTruncationStatement}
 685			\lean{MIPStarRE.LDT.MakingMeasurementsProjective.projectiveLowRankSum_truncate}
 686			Let $\{R_a\}$ be given by \ref{lem:projective-non-measurement}. Write $r_a=\mathrm{rank}(R_a)$ and $r=\sum_a r_a$. If $r \leq d$, take $Q_a=R_a$. Otherwise,
 687			\begin{equation}\label{eq:bound-on-r}
 688				r
 689				=
 690				\sum_a r_a
 691				=
 692				\sum_a \Tr(R_a)
 693				=
 694				\Tr(R)
 695				\leq
 696				(1+2\sqrt{\zeta})d.
 697			\end{equation}
 698			Let $\ket{v_{a,1}},\ldots,\ket{v_{a,r_a}}$ be an orthonormal basis for the range of $R_a$, so
 699			\[
 700				R_a = \sum_{i=1}^{r_a} \ket{v_{a,i}}\bra{v_{a,i}}.
 701			\]
 702			Define the overlaps
 703			\[
 704				o_{a,i} = \bra{\psi} (\ket{v_{a,i}}\bra{v_{a,i}} \ot I)\ket{\psi}.
 705			\]
 706			Their total satisfies
 707			\begin{equation}\label{eq:total-overlap}
 708				\sum_a \sum_{i=1}^{r_a} o_{a,i}
 709				=
 710				\bra{\psi} R \ot I \ket{\psi}
 711				\leq
 712				1+2\sqrt{\zeta}.
 713			\end{equation}
 714			Let $\mathsf{Large}$ be the set of the $d$ largest overlaps $o_{a,i}$, breaking ties arbitrarily, and let $\mathsf{Small}$ be the complement. Then
 715			\begin{equation}\label{eq:size-of-small-is-small}
 716				|\mathsf{Small}|
 717				=
 718				r-d
 719				\leq
 720				2\sqrt{\zeta}\,d
 721				\leq
 722				2\sqrt{\zeta}\,r,
 723			\end{equation}
 724			by \ref{eq:bound-on-r}. Averaging the overlaps over the $r$ indices gives
 725			\begin{equation}\label{eq:small-overlaps}
 726				\sum_{(a,i)\in \mathsf{Small}} o_{a,i}
 727				\leq
 728				\frac{|\mathsf{Small}|}{r}\sum_{a,i} o_{a,i}
 729				\leq
 730				4\sqrt{\zeta},
 731			\end{equation}
 732			using \ref{eq:size-of-small-is-small}, \ref{eq:total-overlap}, and \ref{eq:assumption-on-zeta}.
 733	
 734			For each $a$, let $\mathsf{Large}_a=\{i : (a,i)\in \mathsf{Large}\}$ and define
 735			\[
 736				Q_a = \sum_{i \in \mathsf{Large}_a} \ket{v_{a,i}}\bra{v_{a,i}}.
 737			\]
 738			Then $\sum_a \mathrm{rank}(Q_a)=|\mathsf{Large}| \leq d$, and $Q_a \leq R_a$ for every $a$, so
 739			\[
 740				Q = \sum_a Q_a \leq \sum_a R_a = R \leq (1+2\sqrt{\zeta})I.
 741			\]
 742			Also,
 743			\[
 744				R_a-Q_a = \sum_{i \in \mathsf{Small}_a} \ket{v_{a,i}}\bra{v_{a,i}}
 745			\]
 746			is a projector, hence
 747			\[
 748				\sum_a \Vert (R_a-Q_a)\ot I \ket{\psi}\Vert^2
 749				=
 750				\sum_{(a,i)\in\mathsf{Small}} o_{a,i}
 751				\leq
 752				4\sqrt{\zeta}
 753			\]
 754			by \ref{eq:small-overlaps}. Therefore $R_a \ot I \approx_{4\sqrt{\zeta}} Q_a \ot I$. Combining this with \ref{lem:projective-non-measurement} and the triangle inequality for $\approx_\delta$ gives
 755			\[
 756				A_a \ot I \approx_{12\sqrt{\zeta}} Q_a \ot I.
 757			\]
 758		\end{proof}
